import { FormEvent, MouseEvent, ReactNode, useEffect, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { API_URL, api, money, shortDate } from './api/client'
import type { AutomationPlan, Challenge, Dashboard, DcpAssistantAnalysis, DcpInspection, EmulatorCalibration, EmulatorStatus, InventoryBulkPreview, InventoryBulkResult, InventoryScan, InventoryScanCandidate, InventoryScanCandidatesPage, InventoryScanObservation, Objective, ObjectiveInspection, Player, PlayerInput, Solution, Squad } from './types'

type Page = 'inicio'|'club'|'plantillas'|'dcp'|'objetivos'|'duplicados'|'ia'|'emulador'|'configuracion'
const nav: {id:Page;label:string;icon:string}[] = [
  {id:'inicio',label:'Inicio',icon:'⌂'}, {id:'club',label:'Club',icon:'♙'}, {id:'plantillas',label:'Plantillas',icon:'▦'},
  {id:'dcp',label:'DCP',icon:'◇'}, {id:'objetivos',label:'Objetivos',icon:'◎'}, {id:'duplicados',label:'Duplicados',icon:'⧉'},
  {id:'ia',label:'IA',icon:'✦'}, {id:'emulador',label:'Emulador',icon:'▣'}, {id:'configuracion',label:'Ajustes',icon:'⚙'},
]

function App(){
  const [page,setPage] = useState<Page>('inicio')
  const [dark,setDark] = useState(() => localStorage.getItem('theme') !== 'light')
  useEffect(()=>{ document.documentElement.dataset.theme = dark?'dark':'light'; localStorage.setItem('theme',dark?'dark':'light') },[dark])
  const pages:Record<Page,ReactNode> = {
    inicio:<DashboardPage go={setPage}/>, club:<ClubPage/>, plantillas:<SquadsPage/>, dcp:<ChallengesPage/>,
    objetivos:<ObjectivesPage/>, duplicados:<DuplicatesPage/>, ia:<AiPage/>, emulador:<CompanionPage/>, configuracion:<SettingsPage dark={dark} setDark={setDark}/>,
  }
  return <div className="app-shell">
    <header className="topbar"><div><span className="eyebrow">ASISTENTE LOCAL</span><h1>FC 26 Club Lab</h1></div><span className="local-pill">● Local</span></header>
    <main id="contenido" className="content">{pages[page]}</main>
    <nav className="bottom-nav" aria-label="Navegación principal">{nav.map(item=><button key={item.id} className={page===item.id?'active':''} onClick={()=>setPage(item.id)} aria-current={page===item.id?'page':undefined}><span>{item.icon}</span><small>{item.label}</small></button>)}</nav>
  </div>
}

function Loading(){ return <div className="state"><span className="spinner"/>Cargando datos locales…</div> }
function ErrorBox({error}:{error:unknown}){ return <div className="error-box" role="alert">{error instanceof Error?error.message:'No fue posible cargar esta sección.'}</div> }
function SectionTitle({title,subtitle,action}:{title:string;subtitle?:string;action?:ReactNode}){ return <div className="section-title"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div> }
function Empty({children}:{children:ReactNode}){ return <div className="empty">{children}</div> }

function DashboardPage({go}:{go:(page:Page)=>void}){
  const {data,error,isLoading} = useQuery({queryKey:['dashboard'],queryFn:()=>api<Dashboard>('/dashboard')})
  if(isLoading) return <Loading/>; if(error||!data) return <ErrorBox error={error}/>
  return <>
    <section className="hero"><div><span>Bienvenido a</span><h2>{data.profile.name}</h2><p>{data.profile.platform} · Presupuesto DCP {money(data.profile.max_budget)}</p></div><div className="coin"><small>MONEDAS</small><strong>{money(data.profile.coins)}</strong></div></section>
    <section className="stat-grid">
      <button onClick={()=>go('club')}><span>Jugadores</span><strong>{data.counts.players}</strong></button>
      <button onClick={()=>go('duplicados')}><span>Duplicados</span><strong>{data.counts.duplicates}</strong></button>
      <button onClick={()=>go('dcp')}><span>DCP pendientes</span><strong>{data.counts.pending_challenges}</strong></button>
      <button onClick={()=>go('club')}><span>Protegidos</span><strong>{data.counts.protected}</strong></button>
    </section>
    <section><SectionTitle title="Alertas del club"/><div className="stack">{data.alerts.map((a,i)=><div className={`alert ${a.level}`} key={i}>⚑ {a.message}</div>)}</div></section>
    <section><SectionTitle title="Próximos objetivos" action={<button className="link" onClick={()=>go('objetivos')}>Ver todos</button>}/><div className="stack">{data.objectives.map(o=><ObjectiveRow key={o.id} objective={o}/>)}</div></section>
    <div className="quick-grid"><button className="primary" onClick={()=>go('dcp')}>Optimizar un DCP</button><button onClick={()=>go('club')}>Añadir jugadores</button><button onClick={()=>go('ia')}>Consultar a la IA local</button></div>
  </>
}

const playerSchema = z.object({
  name:z.string().min(1,'Escribe un nombre').max(100), rating:z.coerce.number().int().min(1).max(99), position:z.string().min(1),
  league:z.string().min(1), club:z.string().min(1), nationality:z.string().min(1), card_type:z.string().default('Oro común'),
  rare:z.boolean().default(false), special:z.boolean().default(false), tradable:z.boolean().default(false), price:z.coerce.number().int().min(0),
  chemistry:z.coerce.number().int().min(0).max(3), protected:z.boolean().default(false), starter:z.boolean().default(false),
  squad_role:z.string().default('club'), usefulness:z.coerce.number().int().min(0).max(100), duplicate_untradeable:z.boolean().default(false),
})
type PlayerForm = z.infer<typeof playerSchema>
const emptyPlayer:PlayerForm = {name:'',rating:80,position:'MC',league:'Liga Aurora',club:'Costa FC',nationality:'Colombia',card_type:'Oro común',rare:false,special:false,tradable:false,price:1000,chemistry:1,protected:false,starter:false,squad_role:'club',usefulness:10,duplicate_untradeable:false}

function ClubPage(){
  const qc=useQueryClient(); const [search,setSearch]=useState(''); const [position,setPosition]=useState(''); const [showForm,setShowForm]=useState(false); const [editing,setEditing]=useState<Player|null>(null); const [importFile,setImportFile]=useState<File|null>(null); const [preview,setPreview]=useState<{total:number;preview:PlayerForm[]}|null>(null)
  const query=useQuery({queryKey:['players',search,position],queryFn:()=>api<{items:Player[];total:number}>(`/players?search=${encodeURIComponent(search)}&position=${encodeURIComponent(position)}&limit=200`)})
  const form=useForm<PlayerForm>({resolver:zodResolver(playerSchema),defaultValues:emptyPlayer})
  const save=useMutation({mutationFn:(values:PlayerForm)=>api<Player>(editing?`/players/${editing.id}`:'/players',{method:editing?'PATCH':'POST',body:JSON.stringify(values)}),onSuccess:()=>{qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']});setShowForm(false);setEditing(null);form.reset(emptyPlayer)}})
  const protect=useMutation({mutationFn:(id:number)=>api<Player>(`/players/${id}/protect`,{method:'POST'}),onSuccess:()=>{qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const remove=useMutation({mutationFn:(id:number)=>api(`/players/${id}`,{method:'DELETE'}),onSuccess:()=>{qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const importMutation=useMutation({mutationFn:async(confirm:boolean)=>{if(!importFile)throw new Error('Selecciona un archivo');const data=new FormData();data.append('file',importFile);data.append('confirm',String(confirm));return api<{total?:number;preview?:PlayerForm[];imported?:number}>('/players/import',{method:'POST',body:data})},onSuccess:(data)=>{if(data.preview)setPreview({total:data.total||0,preview:data.preview});if(data.imported){setPreview(null);setImportFile(null);qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']})}}})
  const edit=(p:Player)=>{setEditing(p);form.reset({...p});setShowForm(true)}
  return <>
    <SectionTitle title="Mi club" subtitle={`${query.data?.total??'…'} cartas disponibles`} action={<button className="primary compact" onClick={()=>{setEditing(null);form.reset(emptyPlayer);setShowForm(v=>!v)}}>{showForm?'Cerrar':'+ Jugador'}</button>}/>
    {showForm&&<form className="panel form-grid" onSubmit={form.handleSubmit(v=>save.mutate(v))}>
      <label className="wide">Nombre<input {...form.register('name')}/>{form.formState.errors.name&&<em>{form.formState.errors.name.message}</em>}</label>
      <label>Media<input type="number" {...form.register('rating')}/></label><label>Posición<select {...form.register('position')}>{['POR','LD','DFC','LI','MCD','MC','MCO','ED','DC','EI'].map(x=><option key={x}>{x}</option>)}</select></label>
      <label>Liga<input {...form.register('league')}/></label><label>Club<input {...form.register('club')}/></label><label>Nacionalidad<input {...form.register('nationality')}/></label><label>Tipo<select {...form.register('card_type')}><option>Oro común</option><option>Oro raro</option><option>Especial Eclipse</option></select></label>
      <label>Precio<input type="number" {...form.register('price')}/></label><label>Química<input type="number" {...form.register('chemistry')}/></label><label>Utilidad<input type="number" {...form.register('usefulness')}/></label>
      <div className="check-row wide"><label><input type="checkbox" {...form.register('rare')}/> Raro</label><label><input type="checkbox" {...form.register('special')}/> Especial</label><label><input type="checkbox" {...form.register('tradable')}/> Transferible</label><label><input type="checkbox" {...form.register('duplicate_untradeable')}/> Duplicado</label></div>
      {save.error&&<ErrorBox error={save.error}/>}<button className="primary wide" disabled={save.isPending}>{editing?'Guardar cambios':'Crear jugador'}</button>
    </form>}
    <div className="toolbar"><input aria-label="Buscar jugadores" placeholder="Buscar nombre, club o país" value={search} onChange={e=>setSearch(e.target.value)}/><select aria-label="Filtrar por posición" value={position} onChange={e=>setPosition(e.target.value)}><option value="">Todas las posiciones</option>{['POR','LD','DFC','LI','MCD','MC','MCO','ED','DC','EI'].map(x=><option key={x}>{x}</option>)}</select></div>
    <details className="panel import-panel"><summary>Importar o exportar inventario</summary><div className="import-actions"><input type="file" accept=".csv,.xlsx" onChange={e=>{setImportFile(e.target.files?.[0]||null);setPreview(null)}}/><button onClick={()=>importMutation.mutate(false)} disabled={!importFile||importMutation.isPending}>Revisar archivo</button><a className="button" href={`${API_URL}/players/export?format=csv`}>Exportar CSV</a><a className="button" href={`${API_URL}/players/export?format=xlsx`}>Exportar Excel</a></div>{preview&&<div className="alert warning">Se encontraron {preview.total} filas. Revisa la vista previa y confirma; nada se guarda antes.<div className="mini-list">{preview.preview.slice(0,5).map((p,i)=><span key={i}>{p.name} · {p.rating} · {p.position}</span>)}</div><button className="primary" onClick={()=>importMutation.mutate(true)}>Confirmar importación</button></div>}{importMutation.error&&<ErrorBox error={importMutation.error}/>}</details>
    {query.isLoading?<Loading/>:query.error?<ErrorBox error={query.error}/>:<div className="player-grid">{query.data?.items.map(p=><PlayerCard key={p.id} p={p} onProtect={()=>protect.mutate(p.id)} onEdit={()=>edit(p)} onDelete={()=>{if(confirm(`¿Eliminar ${p.name} del inventario?`))remove.mutate(p.id)}}/>)}</div>}
  </>
}

function PlayerCard({p,onProtect,onEdit,onDelete}:{p:Player;onProtect:()=>void;onEdit:()=>void;onDelete:()=>void}){
  return <article className={`player-card ${p.special?'special':''} ${p.protected?'is-protected':''}`}><div className="rating"><strong>{p.rating}</strong><span>{p.position}</span></div><div className="player-info"><h3>{p.name}</h3><p>{p.club} · {p.league}</p><div className="tags">{p.rare&&<span>Raro</span>}{p.duplicate_untradeable&&<span className="warning-tag">Duplicado</span>}{p.protected&&<span className="safe-tag">🔒 Protegido</span>}</div></div><div className="player-price"><strong>{money(p.price)}</strong><small>{p.tradable?'Transferible':'Intransferible'}</small></div><div className="card-actions"><button onClick={onProtect}>{p.protected?'Desproteger':'Proteger'}</button><button onClick={onEdit}>Editar</button><button className="danger" onClick={onDelete}>Eliminar</button></div></article>
}

function SquadsPage(){
  const qc=useQueryClient(); const query=useQuery({queryKey:['squads'],queryFn:()=>api<Squad[]>('/squads')}); const [recommendation,setRecommendation]=useState<{players:Player[];rating:number;chemistry:number}|null>(null)
  const duplicate=useMutation({mutationFn:(id:number)=>api(`/squads/${id}/duplicate`,{method:'POST'}),onSuccess:()=>qc.invalidateQueries({queryKey:['squads']})})
  const protect=useMutation({mutationFn:(id:number)=>api(`/squads/${id}/protect`,{method:'POST'}),onSuccess:()=>{qc.invalidateQueries({queryKey:['squads']});qc.invalidateQueries({queryKey:['players']})}})
  const recommend=useMutation({mutationFn:()=>api<{players:Player[];rating:number;chemistry:number}>('/squads/recommend',{method:'POST'}),onSuccess:setRecommendation})
  const create=useMutation({mutationFn:()=>api('/squads',{method:'POST',body:JSON.stringify({name:'Plantilla recomendada',formation:'4-3-3',player_ids:recommendation?.players.map(p=>p.id)||[]})}),onSuccess:()=>{setRecommendation(null);qc.invalidateQueries({queryKey:['squads']})}})
  return <><SectionTitle title="Plantillas" subtitle="Compara, duplica y protege equipos" action={<button className="primary compact" onClick={()=>recommend.mutate()}>Recomendar</button>}/>{recommendation&&<div className="panel"><h3>Recomendación 4-3-3</h3><p>Media {recommendation.rating} · Química {recommendation.chemistry}</p><div className="lineup">{recommendation.players.map(p=><span key={p.id}><b>{p.position}</b>{p.name}<small>{p.rating}</small></span>)}</div><button className="primary" onClick={()=>create.mutate()}>Guardar esta plantilla</button></div>}{query.isLoading?<Loading/>:query.error?<ErrorBox error={query.error}/>:<div className="stack">{query.data?.map(s=><article className="panel squad" key={s.id}><div className="split"><div><span className="eyebrow">{s.primary?'PRINCIPAL':'PLANTILLA'}</span><h3>{s.name}</h3><p>{s.formation} · Media {s.rating} · Química {s.chemistry}</p></div>{s.protected&&<span className="safe-tag">🔒 Completa</span>}</div><div className="lineup">{s.players.map(entry=><span key={entry.slot}><b>{entry.player.position}</b>{entry.player.name}<small>{entry.player.rating}</small></span>)}</div><div className="button-row"><button onClick={()=>duplicate.mutate(s.id)}>Duplicar</button><button onClick={()=>protect.mutate(s.id)}>{s.protected?'Desproteger':'Proteger completa'}</button></div></article>)}</div>}</>
}

function ChallengesPage(){
  const qc=useQueryClient(); const query=useQuery({queryKey:['challenges'],queryFn:()=>api<Challenge[]>('/challenges')}); const [results,setResults]=useState<Record<number,Solution[]>>({}); const [message,setMessage]=useState(''); const [createOpen,setCreateOpen]=useState(false); const [draft,setDraft]=useState({name:'Nuevo desafío',segment:'Plantilla única',min_rating:80,min_chemistry:0,min_rare:0})
  const optimize=useMutation({mutationFn:(id:number)=>api<{solutions:Solution[];message:string|null}>(`/segments/${id}/optimize`,{method:'POST',body:JSON.stringify({max_solutions:3,allow_protected_ids:[],exclude_ids:[]})}),onSuccess:(data,id)=>{setResults(r=>({...r,[id]:data.solutions}));setMessage(data.message||'')}})
  const confirmSolution=useMutation({mutationFn:({segment,ids}:{segment:number;ids:number[]})=>api<{submission_id:number}>(`/segments/${segment}/confirm`,{method:'POST',body:JSON.stringify({player_ids:ids})}),onSuccess:(data)=>{setMessage(`Entrega confirmada. Puedes restaurarla con el identificador ${data.submission_id} desde el historial.`);setResults({});qc.invalidateQueries({queryKey:['challenges']});qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const createAutomation=useMutation({mutationFn:({segment,ids}:{segment:number;ids:number[]})=>api<AutomationPlan>('/emulator/plans',{method:'POST',body:JSON.stringify({segment_id:segment,player_ids:ids})}),onSuccess:data=>{setMessage(`Plan asistido #${data.id} creado. Ábrelo en Emulador, calibra la pantalla y confirma las pulsaciones.`);qc.invalidateQueries({queryKey:['automation-plans']})}})
  const createChallenge=useMutation({mutationFn:async()=>{const challenge=await api<Challenge>('/challenges',{method:'POST',body:JSON.stringify({name:draft.name,description:'Desafío creado localmente',reward:''})});await api(`/challenges/${challenge.id}/segments`,{method:'POST',body:JSON.stringify({name:draft.segment,requirements:{squad_size:11,min_rating:Number(draft.min_rating),min_chemistry:Number(draft.min_chemistry),min_rare:Number(draft.min_rare)}})});return challenge},onSuccess:()=>{setCreateOpen(false);qc.invalidateQueries({queryKey:['challenges']});qc.invalidateQueries({queryKey:['dashboard']})}})
  return <><SectionTitle title="Desafíos DCP" subtitle="Soluciones reales, validadas antes de entregar" action={<button className="primary compact" onClick={()=>setCreateOpen(v=>!v)}>+ Crear DCP</button>}/>{createOpen&&<form className="panel form-grid" onSubmit={e=>{e.preventDefault();createChallenge.mutate()}}><label className="wide">Nombre<input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} required/></label><label className="wide">Segmento<input value={draft.segment} onChange={e=>setDraft({...draft,segment:e.target.value})} required/></label><label>Media mínima<input type="number" min="1" max="99" value={draft.min_rating} onChange={e=>setDraft({...draft,min_rating:Number(e.target.value)})}/></label><label>Química mínima<input type="number" min="0" max="33" value={draft.min_chemistry} onChange={e=>setDraft({...draft,min_chemistry:Number(e.target.value)})}/></label><label>Raros mínimos<input type="number" min="0" max="11" value={draft.min_rare} onChange={e=>setDraft({...draft,min_rare:Number(e.target.value)})}/></label><button className="primary wide" disabled={createChallenge.isPending}>Guardar desafío y segmento</button></form>}{message&&<div className="alert info">{message}</div>}{query.isLoading?<Loading/>:query.error?<ErrorBox error={query.error}/>:<div className="stack">{query.data?.map(c=><article className={`challenge panel ${c.completed?'done':''}`} key={c.id}><div className="split"><div><span className="eyebrow">{c.completed?'COMPLETADO':'DCP ACTIVO'}</span><h3>{c.name}</h3><p>{c.description}</p></div><span className="reward">{c.reward}</span></div>{c.segments.map(s=><div className="segment" key={s.id}><div><h4>{s.completed?'✓ ':''}{s.name}</h4><RequirementTags requirements={s.requirements}/></div><button className="primary compact" disabled={s.completed||optimize.isPending} onClick={()=>optimize.mutate(s.id)}>{optimize.isPending?'Calculando…':'Optimizar'}</button>{results[s.id]?.map((solution,index)=><div className="solution" key={index}><div className="solution-head"><strong>Solución {index+1} · Media {solution.rating}</strong><span>{solution.duplicate_count} duplicados · {money(solution.total_cost)}</span></div><div className="solution-players">{solution.players.map(p=><span key={p.id}>{p.rating} {p.position} · {p.name}{p.duplicate_untradeable?' ⧉':''}</span>)}</div><div className="button-row"><button onClick={()=>createAutomation.mutate({segment:s.id,ids:solution.player_ids})}>Preparar en emulador</button><button className="danger-fill" onClick={()=>{if(confirm('Esta acción consumirá los jugadores. ¿Confirmar entrega?'))confirmSolution.mutate({segment:s.id,ids:solution.player_ids})}}>Confirmar entrega local</button></div></div>)}</div>)}</article>)}</div>}{(optimize.error||confirmSolution.error||createChallenge.error||createAutomation.error)&&<ErrorBox error={optimize.error||confirmSolution.error||createChallenge.error||createAutomation.error}/>}</>
}

function RequirementTags({requirements}:{requirements:Record<string,unknown>}){ const labels:Record<string,string>={squad_size:'Jugadores',min_rating:'Media mín.',min_chemistry:'Química mín.',min_rare:'Raros mín.',min_special:'Especiales mín.',min_leagues:'Ligas mín.',max_leagues:'Ligas máx.',required_nation:'Nación'}; return <div className="tags">{Object.entries(requirements).filter(([k])=>labels[k]).map(([k,v])=><span key={k}>{labels[k]}: {String(v)}</span>)}</div> }

const objectiveSchema=z.object({name:z.string().min(2),description:z.string(),category:z.string(),progress:z.coerce.number().min(0),target:z.coerce.number().min(1),expires_at:z.string().optional()})
type ObjectiveForm=z.infer<typeof objectiveSchema>
function ObjectivesPage(){
  const qc=useQueryClient(); const [open,setOpen]=useState(false); const query=useQuery({queryKey:['objectives'],queryFn:()=>api<Objective[]>('/objectives')}); const form=useForm<ObjectiveForm>({resolver:zodResolver(objectiveSchema),defaultValues:{name:'',description:'',category:'Objetivo',progress:0,target:1,expires_at:''}})
  const create=useMutation({mutationFn:(v:ObjectiveForm)=>api('/objectives',{method:'POST',body:JSON.stringify({...v,expires_at:v.expires_at?new Date(v.expires_at).toISOString():null})}),onSuccess:()=>{form.reset();setOpen(false);qc.invalidateQueries({queryKey:['objectives']})}})
  const progress=useMutation({mutationFn:({id,value}:{id:number;value:number})=>api(`/objectives/${id}`,{method:'PATCH',body:JSON.stringify({progress:value})}),onSuccess:()=>{qc.invalidateQueries({queryKey:['objectives']});qc.invalidateQueries({queryKey:['dashboard']})}})
  return <><SectionTitle title="Objetivos" subtitle="Progreso y vencimientos en un solo lugar" action={<button className="primary compact" onClick={()=>setOpen(v=>!v)}>+ Objetivo</button>}/>{open&&<form className="panel form-grid" onSubmit={form.handleSubmit(v=>create.mutate(v))}><label className="wide">Nombre<input {...form.register('name')}/></label><label className="wide">Descripción<input {...form.register('description')}/></label><label>Categoría<select {...form.register('category')}><option>Objetivo</option><option>Evolución</option></select></label><label>Meta<input type="number" {...form.register('target')}/></label><label>Vence<input type="datetime-local" {...form.register('expires_at')}/></label><button className="primary wide">Guardar objetivo</button></form>}{query.isLoading?<Loading/>:query.error?<ErrorBox error={query.error}/>:<div className="stack">{query.data?.map(o=><div className="panel" key={o.id}><ObjectiveRow objective={o}/><div className="button-row"><button disabled={o.completed} onClick={()=>progress.mutate({id:o.id,value:Math.min(o.target,o.progress+1)})}>+1 progreso</button><button disabled={o.completed} onClick={()=>progress.mutate({id:o.id,value:o.target})}>Completar</button></div></div>)}</div>}</>
}
function ObjectiveRow({objective:o}:{objective:Objective}){ const percentage=Math.min(100,Math.round(o.progress/o.target*100)); return <div className={`objective ${o.completed?'complete':''}`}><div className="split"><div><span className="eyebrow">{o.category}</span><h3>{o.name}</h3><p>Vence: {shortDate(o.expires_at)}</p></div><strong>{o.progress}/{o.target}</strong></div><div className="progress"><span style={{width:`${percentage}%`}}/></div></div> }

function DuplicatesPage(){
  const qc=useQueryClient(); const query=useQuery({queryKey:['duplicates'],queryFn:()=>api<Player[]>('/duplicates')}); const challenges=useQuery({queryKey:['challenges'],queryFn:()=>api<Challenge[]>('/challenges')}); const used=useMutation({mutationFn:(id:number)=>api(`/duplicates/${id}/used`,{method:'POST'}),onSuccess:()=>{qc.invalidateQueries({queryKey:['duplicates']});qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']})}})
  return <><SectionTitle title="Duplicados" subtitle="Los intransferibles reciben prioridad en el optimizador"/>{query.isLoading?<Loading/>:query.error?<ErrorBox error={query.error}/>:!query.data?.length?<Empty>No hay duplicados pendientes.</Empty>:<div className="stack">{query.data.map(p=><div className="panel duplicate-row" key={p.id}><div className="split"><div><span className="eyebrow">DUPLICADO INTRANSFERIBLE</span><h3>{p.rating} {p.position} · {p.name}</h3><p>{p.club} · {p.league}</p></div><strong>{money(p.price)}</strong></div><div className="compatible"><strong>DCP compatibles por media:</strong>{challenges.data?.flatMap(c=>c.segments.filter(s=>Number(s.requirements.min_rating||0)<=p.rating).map(s=><span key={s.id}>{c.name} · {s.name}</span>)).slice(0,4)}</div><button onClick={()=>used.mutate(p.id)}>Marcar como utilizado</button></div>)}</div>}</>
}

function AiPage(){
  const qc=useQueryClient()
  const statusQuery=useQuery({queryKey:['ai-status'],queryFn:()=>api<{available:boolean;model:string}>('/ai/status'),refetchInterval:30_000})
  const history=useQuery({queryKey:['ai-history'],queryFn:()=>api<{id:number;role:string;content:string}[]>('/ai/history')})
  const challenges=useQuery({queryKey:['challenges'],queryFn:()=>api<Challenge[]>('/challenges')})
  const pendingSegments=(challenges.data||[]).flatMap(challenge=>challenge.segments.filter(segment=>!segment.completed).map(segment=>({challenge,segment})))
  const [message,setMessage]=useState('¿Qué DCP puedo completar usando mis duplicados?')
  const [selectedSegmentId,setSelectedSegmentId]=useState(0)
  const [preserveStarters,setPreserveStarters]=useState(true)
  const [maxSolutions,setMaxSolutions]=useState(3)
  const [analysis,setAnalysis]=useState<DcpAssistantAnalysis|null>(null)
  const [selectedSolution,setSelectedSolution]=useState(0)
  const [planConfirmation,setPlanConfirmation]=useState('')
  const [planCreated,setPlanCreated]=useState('')
  useEffect(()=>{if(!selectedSegmentId&&pendingSegments.length)setSelectedSegmentId(pendingSegments[0].segment.id)},[selectedSegmentId,challenges.data])
  const ask=useMutation({mutationFn:()=>api<{answer:string}>('/ai/chat',{method:'POST',body:JSON.stringify({message})}),onSuccess:()=>{qc.invalidateQueries({queryKey:['ai-history']});setMessage('')}})
  const analyze=useMutation({mutationFn:({segmentId,preserve}:{segmentId:number;preserve:boolean})=>api<DcpAssistantAnalysis>('/ai/dcp/analyze',{method:'POST',body:JSON.stringify({segment_id:segmentId,preserve_starters:preserve,max_solutions:maxSolutions})}),onSuccess:data=>{setAnalysis(data);setSelectedSolution(0);setPlanConfirmation('');setPlanCreated('')}})
  const createPlan=useMutation({mutationFn:(solution:Solution)=>api<AutomationPlan>('/emulator/plans',{method:'POST',body:JSON.stringify({segment_id:analysis!.segment.id,player_ids:solution.player_ids})}),onSuccess:data=>{setPlanCreated(`Plan asistido #${data.id} creado. Revísalo en Emulador; todavía necesitará la confirmación PREPARAR ${data.id} y nunca pulsará la entrega final.`);setPlanConfirmation('');qc.invalidateQueries({queryKey:['automation-plans']})}})
  const submit=(e:FormEvent)=>{e.preventDefault();if(message.trim())ask.mutate()}
  const chosenSolution=analysis?.solutions[selectedSolution]
  const expectedPlanPhrase=analysis?.plan_confirmation_phrase||''
  const resetAnalysis=(segmentId:number)=>{setSelectedSegmentId(segmentId);setAnalysis(null);setPlanConfirmation('');setPlanCreated('')}
  return <>
    <SectionTitle title="Asistente DCP local" subtitle={`Análisis determinista + explicación con ${statusQuery.data?.model||'qwen2.5:3b'}`}/>
    <div className={`ai-status ${statusQuery.data?.available?'online':'offline'}`}><span>●</span>{statusQuery.data?.available?'Ollama disponible para explicar. Los cálculos los realiza el optimizador local.':'Ollama no está disponible, pero el análisis y cálculo DCP siguen funcionando localmente.'}</div>
    <section className="panel"><span className="eyebrow">ANÁLISIS GUIADO · SIN CONSUMIR CARTAS</span><h3>Vamos paso a paso</h3><p>El asistente pregunta, calcula con el inventario registrado y te muestra propuestas. No compra, vende, entrega ni modifica cartas durante el análisis.</p>
      {challenges.isLoading?<Loading/>:!pendingSegments.length?<Empty>No hay segmentos DCP pendientes. Crea o lee un DCP para comenzar.</Empty>:<div className="form-grid">
        <label className="wide">1. ¿Qué DCP quieres calcular?<select value={selectedSegmentId} onChange={e=>resetAnalysis(Number(e.target.value))}>{pendingSegments.map(({challenge,segment})=><option key={segment.id} value={segment.id}>{challenge.name} · {segment.name}</option>)}</select></label>
        <label className="check wide"><input type="checkbox" checked={preserveStarters} onChange={e=>{setPreserveStarters(e.target.checked);setAnalysis(null);setPlanConfirmation('')}}/> 2. ¿Quieres conservar todos tus titulares? {preserveStarters?'Sí, excluirlos':'No, permitirlos en propuestas'}</label>
        <label>3. ¿Cuántas propuestas?<select value={maxSolutions} onChange={e=>{setMaxSolutions(Number(e.target.value));setAnalysis(null)}}><option value={1}>1 propuesta</option><option value={2}>2 propuestas</option><option value={3}>3 propuestas</option></select></label>
        <button className="primary wide" disabled={!selectedSegmentId||analyze.isPending} onClick={()=>analyze.mutate({segmentId:selectedSegmentId,preserve:preserveStarters})}>{analyze.isPending?'Calculando con OR-Tools…':'Analizar mi club'}</button>
      </div>}
      {analysis&&<div className="stack"><div className="bubble assistant"><strong>Análisis local</strong><span>{analysis.assistant.summary}</span><span>{analysis.assistant.question}</span></div><div className="tags"><span>{analysis.inventory_summary.available} cartas revisadas</span><span>{analysis.inventory_summary.pending_review} pendientes de revisión</span><span>{analysis.inventory_summary.duplicates} duplicados</span><span>{analysis.inventory_summary.protected} protegidas excluidas</span><span>{analysis.inventory_summary.starters_excluded} titulares excluidos</span></div>{analysis.inventory_summary.pending_review>0&&<div className="alert warning">Hay cartas detectadas desde Companion que todavía no participan en el cálculo. Revísalas e impórtalas, y después vuelve a analizar.</div>}<RequirementTags requirements={analysis.segment.requirements}/>
        {analysis.alternative_with_starters&&<button onClick={()=>{setPreserveStarters(false);analyze.mutate({segmentId:analysis.segment.id,preserve:false})}}>Recalcular permitiendo titulares</button>}
        {analysis.solutions.map((solution,index)=><article className="solution" key={index}><div className="solution-head"><strong>Propuesta {index+1} · Media {solution.rating} · Química {solution.chemistry}</strong><span>{solution.duplicate_count} duplicados · sacrificio {solution.total_cost}</span></div><div className="solution-players">{solution.players.map(player=><span key={player.id}>{player.rating} {player.position} · {player.name}{player.duplicate_untradeable?' ⧉':''}</span>)}</div><button className={selectedSolution===index?'primary':''} onClick={()=>{setSelectedSolution(index);setPlanConfirmation('')}}>{selectedSolution===index?'Propuesta seleccionada':'Elegir esta propuesta'}</button></article>)}
        {chosenSolution&&<div className="confirmation-box"><h3>Confirmación antes de gestionar</h3><p>Revisa los {chosenSolution.player_ids.length} jugadores. Para crear únicamente el borrador del plan escribe <code>{expectedPlanPhrase}</code>.</p><div className="button-row"><input value={planConfirmation} onChange={e=>setPlanConfirmation(e.target.value)} placeholder={expectedPlanPhrase}/><button className="primary" disabled={planConfirmation!==expectedPlanPhrase||createPlan.isPending} onClick={()=>createPlan.mutate(chosenSolution)}>{createPlan.isPending?'Creando…':'Crear plan revisable'}</button></div><p>Después, en Emulador, deberás confirmar de nuevo con <code>PREPARAR &lt;id&gt;</code>. La entrega final siempre queda en tus manos.</p></div>}
        {planCreated&&<div className="alert info">{planCreated}</div>}
      </div>}
      {(challenges.error||analyze.error||createPlan.error)&&<ErrorBox error={challenges.error||analyze.error||createPlan.error}/>}
    </section>
    <SectionTitle title="Preguntar al copiloto" subtitle="Usa resúmenes controlados; nunca puede modificar la base"/>
    <div className="chat panel">{!history.data?.length&&<div className="empty">Pregunta por tu inventario, duplicados, requisitos u objetivos. Para elegir jugadores usa el análisis guiado superior.</div>}{history.data?.map(item=>item.role==='user'?<p className="bubble user" key={item.id}>{item.content}</p>:<div className="bubble assistant" key={item.id}><strong>Respuesta local</strong>{item.content}</div>)}{ask.isPending&&<Loading/>}</div>
    <form className="chat-form" onSubmit={submit}><textarea value={message} maxLength={2000} onChange={e=>setMessage(e.target.value)} placeholder="Escribe una consulta…"/><button className="primary" disabled={ask.isPending||!message.trim()}>Enviar</button></form>
    {ask.error&&<ErrorBox error={ask.error}/>}<div className="alert warning">No es una conexión oficial con EA. No solicita credenciales y nunca realiza la entrega final.</div>
  </>
}

const defaultCalibration:EmulatorCalibration={screen_width:1080,screen_height:2400,open_search_x:940,open_search_y:2120,search_field_x:520,search_field_y:310,first_result_x:520,first_result_y:690,add_player_x:900,add_player_y:2180,wait_ms:900}
const calibrationPoints={open_search:['open_search_x','open_search_y'],search_field:['search_field_x','search_field_y'],first_result:['first_result_x','first_result_y'],add_player:['add_player_x','add_player_y']} as const
type CalibrationTarget=keyof typeof calibrationPoints
type ReviewedScanPlayer=PlayerInput&{candidate_id:number;selected:boolean}
const reviewCandidate=(candidate:InventoryScanCandidate):ReviewedScanPlayer=>({candidate_id:candidate.candidate_id,selected:false,name:candidate.name,rating:candidate.rating||80,position:candidate.position||'MC',league:'Por revisar',club:'Por revisar',nationality:'Por revisar',card_type:'Oro común',rare:false,special:false,tradable:false,price:0,chemistry:0,protected:false,starter:false,squad_role:'club',usefulness:0,duplicate_untradeable:false})
const reviewedPayload=(player:ReviewedScanPlayer):PlayerInput=>({name:player.name,rating:Number(player.rating),position:player.position,league:player.league,club:player.club,nationality:player.nationality,card_type:player.card_type,rare:player.rare,special:player.special,tradable:player.tradable,price:Number(player.price),chemistry:Number(player.chemistry),protected:player.protected,starter:player.starter,squad_role:player.squad_role,usefulness:Number(player.usefulness),duplicate_untradeable:player.duplicate_untradeable})
function CompanionPage(){
  const qc=useQueryClient()
  const [address,setAddress]=useState('host.docker.internal:5555')
  const [pairAddress,setPairAddress]=useState('192.168.1.20:37001')
  const [pairingCode,setPairingCode]=useState('')
  const [screen,setScreen]=useState<string|null>(null)
  const [inspection,setInspection]=useState<{raw_text:string;candidates:{name:string;rating:number|null;position:string}[]}|null>(null)
  const [dcpInspection,setDcpInspection]=useState<DcpInspection|null>(null)
  const [objectiveInspection,setObjectiveInspection]=useState<ObjectiveInspection|null>(null)
  const [detectedDcpName,setDetectedDcpName]=useState('DCP leído desde Companion')
  const [dcpConfirmation,setDcpConfirmation]=useState('')
  const [objectiveConfirmation,setObjectiveConfirmation]=useState('')
  const [calibration,setCalibration]=useState<EmulatorCalibration>(defaultCalibration)
  const [calibrationTarget,setCalibrationTarget]=useState<CalibrationTarget|null>(null)
  const [confirmations,setConfirmations]=useState<Record<number,string>>({})
  const [selectedScanId,setSelectedScanId]=useState<number|null>(null)
  const [reviewed,setReviewed]=useState<ReviewedScanPlayer[]>([])
  const [reviewPage,setReviewPage]=useState(1)
  const [scanConfirmation,setScanConfirmation]=useState('')
  const [archiveDemo,setArchiveDemo]=useState(false)
  const [bulkConfirmation,setBulkConfirmation]=useState('')

  const status=useQuery({queryKey:['emulator-status'],queryFn:()=>api<EmulatorStatus>('/emulator/status'),refetchInterval:10000})
  const plans=useQuery({queryKey:['automation-plans'],queryFn:()=>api<AutomationPlan[]>('/emulator/plans'),refetchInterval:2500})
  const scans=useQuery({queryKey:['inventory-scans'],queryFn:()=>api<InventoryScan[]>('/emulator/scans'),staleTime:30000,refetchOnWindowFocus:false})
  const openScans=scans.data?.filter(item=>['scanning','review'].includes(item.status))||[]
  const activeScan=openScans.find(item=>item.id===selectedScanId)||openScans[0]
  const bulkPreview=useQuery({queryKey:['inventory-bulk-preview'],queryFn:()=>api<InventoryBulkPreview>('/emulator/scans/bulk-preview'),enabled:openScans.length>0,staleTime:30000,refetchOnWindowFocus:false})
  const scanCandidates=useQuery({
    queryKey:['inventory-scan-candidates',activeScan?.id,reviewPage],
    queryFn:()=>api<InventoryScanCandidatesPage>(`/emulator/scans/${activeScan!.id}/candidates?offset=${(reviewPage-1)*20}&limit=20`),
    enabled:Boolean(activeScan?.candidate_count),
    staleTime:30000,
    gcTime:0,
    refetchOnWindowFocus:false,
  })

  useEffect(()=>{if(status.data?.config.address)setAddress(status.data.config.address);if(status.data?.config.calibration)setCalibration(status.data.config.calibration)},[status.data?.config.address,status.data?.config.calibration])
  useEffect(()=>()=>{if(screen)URL.revokeObjectURL(screen)},[screen])
  useEffect(()=>{setReviewed((scanCandidates.data?.items||[]).map(reviewCandidate))},[scanCandidates.data])

  const connect=useMutation({mutationFn:()=>api('/emulator/connect',{method:'POST',body:JSON.stringify({address})}),onSuccess:()=>qc.invalidateQueries({queryKey:['emulator-status']})})
  const pair=useMutation({mutationFn:()=>api('/emulator/pair',{method:'POST',body:JSON.stringify({address:pairAddress,pairing_code:pairingCode})}),onSuccess:()=>setPairingCode('')})
  const selectDevice=useMutation({mutationFn:(serial:string)=>api('/emulator/select',{method:'POST',body:JSON.stringify({serial})}),onSuccess:()=>qc.invalidateQueries({queryKey:['emulator-status']})})
  const capture=useMutation({mutationFn:async()=>{const response=await fetch(`${API_URL}/emulator/screenshot`,{cache:'no-store'});if(!response.ok){let message='No se pudo capturar la pantalla';try{const data=await response.json();message=data.detail||message}catch{/* respuesta no JSON */}throw new Error(message)}return URL.createObjectURL(await response.blob())},onSuccess:url=>setScreen(previous=>{if(previous)URL.revokeObjectURL(previous);return url})})
  const inspect=useMutation({mutationFn:()=>api<typeof inspection>('/emulator/inspect',{method:'POST'}),onSuccess:setInspection})
  const inspectDcp=useMutation({mutationFn:()=>api<DcpInspection>('/emulator/dcp/inspect',{method:'POST'}),onSuccess:data=>{setDcpInspection(data);setDcpConfirmation('')}})
  const inspectObjectives=useMutation({mutationFn:()=>api<ObjectiveInspection>('/emulator/objectives/inspect',{method:'POST'}),onSuccess:data=>{setObjectiveInspection(data);setObjectiveConfirmation('')}})
  const tap=useMutation({mutationFn:({x,y}:{x:number;y:number})=>api('/emulator/tap',{method:'POST',body:JSON.stringify({x,y})}),onSuccess:()=>setTimeout(()=>capture.mutate(),500)})
  const swipe=useMutation({mutationFn:(direction:'up'|'down')=>{const x=Math.round(calibration.screen_width/2);const top=Math.round(calibration.screen_height*.25),bottom=Math.round(calibration.screen_height*.75);return api('/emulator/swipe',{method:'POST',body:JSON.stringify({x1:x,y1:direction==='up'?bottom:top,x2:x,y2:direction==='up'?top:bottom,duration_ms:400})})},onSuccess:()=>setTimeout(()=>capture.mutate(),650)})
  const saveCalibration=useMutation({mutationFn:()=>api<EmulatorCalibration>('/emulator/calibration',{method:'PUT',body:JSON.stringify(calibration)}),onSuccess:()=>qc.invalidateQueries({queryKey:['emulator-status']})})
  const startScan=useMutation({mutationFn:()=>api<InventoryScan>('/emulator/scans',{method:'POST'}),onSuccess:data=>{setSelectedScanId(data.id);setReviewed([]);setReviewPage(1);setScanConfirmation('');qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-bulk-preview']})}})
  const continueScan=useMutation({mutationFn:(id:number)=>api<InventoryScan>(`/emulator/scans/${id}/continue`,{method:'POST'}),onSuccess:data=>{setSelectedScanId(data.id);setReviewed([]);setReviewPage(1);setScanConfirmation('');qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-bulk-preview']})}})
  const observeScan=useMutation({mutationFn:(id:number)=>api<InventoryScanObservation>(`/emulator/scans/${id}/observe`,{method:'POST'}),onSuccess:data=>{qc.setQueryData<InventoryScan[]>(['inventory-scans'],rows=>rows?.map(scan=>scan.id===data.scan.id?data.scan:scan));qc.invalidateQueries({queryKey:['inventory-bulk-preview']});if(data.detected){setReviewed([]);setReviewPage(Math.max(1,Math.ceil(data.scan.candidate_count/20)));setScanConfirmation('');qc.invalidateQueries({queryKey:['inventory-scan-candidates',data.scan.id]})}}})
  const captureScan=useMutation({mutationFn:(id:number)=>api<{scan:InventoryScan;detected:number;duplicate_capture:boolean}>(`/emulator/scans/${id}/capture`,{method:'POST'}),onSuccess:data=>{setReviewed([]);setReviewPage(Math.max(1,Math.ceil(data.scan.candidate_count/20)));qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-scan-candidates',data.scan.id]});qc.invalidateQueries({queryKey:['inventory-bulk-preview']})}})
  const advanceScan=useMutation({mutationFn:(id:number)=>api<{scan:InventoryScan;detected:number;duplicate_capture:boolean}>(`/emulator/scans/${id}/advance`,{method:'POST'}),onSuccess:data=>{setReviewed([]);setReviewPage(Math.max(1,Math.ceil(data.scan.candidate_count/20)));qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-scan-candidates',data.scan.id]});qc.invalidateQueries({queryKey:['inventory-bulk-preview']})}})
  const importScan=useMutation({mutationFn:(scan:InventoryScan)=>{const selected=reviewed.filter(item=>item.selected);return api(`/emulator/scans/${scan.id}/import`,{method:'POST',body:JSON.stringify({players:selected.map(reviewedPayload),candidate_ids:selected.map(item=>item.candidate_id),confirmation:scanConfirmation,archive_demo:archiveDemo})})},onSuccess:()=>{setReviewed([]);setReviewPage(1);setScanConfirmation('');qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-scan-candidates']});qc.invalidateQueries({queryKey:['inventory-bulk-preview']});qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const reconcileScans=useMutation({mutationFn:()=>api<InventoryBulkPreview&{duplicates_removed:number;registered_or_used_removed:number}>('/emulator/scans/reconcile',{method:'POST'}),onSuccess:()=>{setReviewed([]);setReviewPage(1);qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-scan-candidates']});qc.invalidateQueries({queryKey:['inventory-bulk-preview']})}})
  const bulkImport=useMutation({mutationFn:()=>api<InventoryBulkResult>('/emulator/scans/bulk-import',{method:'POST',body:JSON.stringify({confirmation:bulkConfirmation})}),onSuccess:()=>{setBulkConfirmation('');setReviewed([]);setReviewPage(1);qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-scan-candidates']});qc.invalidateQueries({queryKey:['inventory-bulk-preview']});qc.invalidateQueries({queryKey:['players']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const cancelScan=useMutation({mutationFn:(id:number)=>api(`/emulator/scans/${id}/cancel`,{method:'POST'}),onSuccess:()=>{setSelectedScanId(null);setReviewed([]);qc.invalidateQueries({queryKey:['inventory-scans']});qc.invalidateQueries({queryKey:['inventory-bulk-preview']});qc.removeQueries({queryKey:['inventory-scan-candidates']})}})
  const syncDetectedDcp=useMutation({mutationFn:()=>{if(!dcpInspection)throw new Error('Lee primero la pantalla del DCP');return api<{challenge_id:number;action:string}>('/emulator/dcp/sync',{method:'POST',body:JSON.stringify({name:detectedDcpName,requirements:dcpInspection.detected_requirements,confirmation:dcpConfirmation})})},onSuccess:()=>{setDcpConfirmation('');qc.invalidateQueries({queryKey:['challenges']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const syncObjectives=useMutation({mutationFn:()=>{if(!objectiveInspection?.objectives.length)throw new Error('Lee primero la pantalla Objetivos');return api<{created:number;updated:number}>('/emulator/objectives/sync',{method:'POST',body:JSON.stringify({objectives:objectiveInspection.objectives,confirmation:objectiveConfirmation})})},onSuccess:()=>{setObjectiveConfirmation('');qc.invalidateQueries({queryKey:['objectives']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const prepare=useMutation({mutationFn:(id:number)=>api<AutomationPlan>(`/emulator/plans/${id}/prepare`,{method:'POST'}),onSuccess:()=>qc.invalidateQueries({queryKey:['automation-plans']})})
  const execute=useMutation({mutationFn:(plan:AutomationPlan)=>api(`/emulator/plans/${plan.id}/execute`,{method:'POST',body:JSON.stringify({confirmation:confirmations[plan.id]||''})}),onSuccess:()=>qc.invalidateQueries({queryKey:['automation-plans']})})
  const cancel=useMutation({mutationFn:(id:number)=>api(`/emulator/plans/${id}/cancel`,{method:'POST'}),onSuccess:()=>qc.invalidateQueries({queryKey:['automation-plans']})})

  const clickScreen=(event:MouseEvent<HTMLImageElement>)=>{const rect=event.currentTarget.getBoundingClientRect();const x=Math.round((event.clientX-rect.left)/rect.width*event.currentTarget.naturalWidth);const y=Math.round((event.clientY-rect.top)/rect.height*event.currentTarget.naturalHeight);if(calibrationTarget){const [xKey,yKey]=calibrationPoints[calibrationTarget];setCalibration({...calibration,screen_width:event.currentTarget.naturalWidth,screen_height:event.currentTarget.naturalHeight,[xKey]:x,[yKey]:y});setCalibrationTarget(null);return}tap.mutate({x,y})}
  const updateReviewed=(id:number,field:keyof ReviewedScanPlayer,value:string|number|boolean)=>setReviewed(items=>items.map(item=>item.candidate_id===id?({...item,[field]:value} as ReviewedScanPlayer):item))
  const reviewPageCount=Math.max(1,Math.ceil((activeScan?.candidate_count||0)/20))
  const changeReviewPage=(page:number)=>{setReviewed([]);setScanConfirmation('');setReviewPage(Math.max(1,Math.min(reviewPageCount,page)))}
  const selectedPlayers=reviewed.filter(item=>item.selected)
  const expectedScanPhrase=activeScan?(archiveDemo?activeScan.archive_demo_phrase:activeScan.confirmation_phrase):''
  const anyError=(status.data?.available?null:connect.error)||pair.error||selectDevice.error||capture.error||inspect.error||inspectDcp.error||inspectObjectives.error||tap.error||swipe.error||saveCalibration.error||startScan.error||continueScan.error||observeScan.error||captureScan.error||advanceScan.error||importScan.error||reconcileScans.error||bulkImport.error||cancelScan.error||scanCandidates.error||syncDetectedDcp.error||syncObjectives.error||prepare.error||execute.error||cancel.error

  return <>
    <SectionTitle title="Conexión con Companion" subtitle="Lee tu club, calcula el DCP y prepara jugadores sin entregar automáticamente"/>
    <div className={`ai-status ${status.data?.available?'online':'offline'}`}><span>●</span>{status.data?.available?`Dispositivo conectado: ${status.data.devices.find(d=>d.state==='device')?.serial}`:status.data?.message||'Comprobando ADB…'}</div>
    <section className="panel"><h3>Progreso de configuración</h3><div className="mini-list"><span>{status.data?.enabled?'✓':'○'} Puente ADB habilitado</span><span>{status.data?.available?'✓':'○'} Teléfono o emulador conectado</span><span>{screen?'✓':'○'} Captura visible</span><span>{status.data?.config.calibration?'✓':'○'} Coordenadas guardadas</span><span>{scans.data?.some(item=>item.status==='imported')?'✓':'○'} Inventario real revisado e importado</span></div></section>
    <section className="panel companion-update-callout"><div className="split"><div><span className="eyebrow">ACTUALIZACIÓN MANUAL</span><h3>Traer cartas desde Companion</h3><p>{activeScan?`Lectura #${activeScan.id}: ${activeScan.candidate_count} candidatos pendientes.`:'Primero crea una lectura para acumular las cartas visibles.'}</p></div><div className="button-row">{activeScan?<button className="primary" disabled={!status.data?.available||observeScan.isPending||selectedPlayers.length>0||activeScan.captured_pages>=50||activeScan.candidate_count>=1000} onClick={()=>observeScan.mutate(activeScan.id)}>{observeScan.isPending?'Leyendo Companion…':'Actualizar desde Companion'}</button>:<button className="primary" disabled={!status.data?.available||startScan.isPending} onClick={()=>startScan.mutate()}>{startScan.isPending?'Creando…':'Crear lectura'}</button>}{bulkPreview.data&&bulkPreview.data.unique_new>0&&<button onClick={()=>document.getElementById('carga-completa')?.scrollIntoView({behavior:'smooth',block:'start'})}>Cargar las {bulkPreview.data.unique_new} únicas</button>}</div></div>{observeScan.data?.message&&<div className="alert info">{observeScan.data.message}</div>}{selectedPlayers.length>0&&<p>Importa o desmarca la selección actual antes de actualizar para no perder tus cambios.</p>}</section>
    <section className="panel"><h3>Conexión ADB</h3><p>Inicia sesión tú mismo en Companion. Esta aplicación nunca solicita ni almacena credenciales.</p>{status.data?.devices.some(device=>device.state==='device')&&<div className="button-row">{status.data.devices.filter(device=>device.state==='device').map(device=><button key={device.serial} className={status.data?.config.serial===device.serial?'primary':''} disabled={selectDevice.isPending||status.data?.config.serial===device.serial} onClick={()=>selectDevice.mutate(device.serial)}>{status.data?.config.serial===device.serial?'AVD seleccionado':`Usar ${device.serial}`}</button>)}</div>}<div className="button-row"><input value={address} onChange={e=>setAddress(e.target.value)} placeholder="host.docker.internal:5555"/><button className="primary" disabled={connect.isPending||status.data?.available} onClick={()=>connect.mutate()}>{status.data?.available?'ADB ya conectado':'Conectar'}</button></div><details><summary>Emparejar un teléfono por depuración inalámbrica</summary><p>Android muestra una dirección/puerto de emparejamiento y un código temporal. El código se usa una vez y nunca se guarda ni audita.</p><div className="form-grid"><label>Dirección de emparejamiento<input value={pairAddress} onChange={e=>setPairAddress(e.target.value)} placeholder="192.168.1.20:37001"/></label><label>Código de 6 dígitos<input value={pairingCode} inputMode="numeric" maxLength={6} onChange={e=>setPairingCode(e.target.value.replace(/\D/g,''))}/></label><button className="primary wide" disabled={pair.isPending||pairingCode.length!==6} onClick={()=>pair.mutate()}>Emparejar</button></div><p>Después usa en “Conectar” la dirección y el puerto que Android muestra para conexión, que puede ser distinto al puerto de emparejamiento.</p></details></section>

    <section className="panel"><div className="split"><div><h3>Pantalla remota</h3><p>{calibrationTarget?`Pulsa la zona “${calibrationTarget.replaceAll('_',' ')}”; este clic solo mide y no toca el dispositivo.`:'Un clic normal envía un toque. Activa antes un punto de calibración para medir sin tocar.'}</p></div><button disabled={!status.data?.available||capture.isPending} onClick={()=>capture.mutate()}>Actualizar</button></div>{screen?<img className={`device-screen ${calibrationTarget?'calibrating':''}`} src={screen} onClick={clickScreen} alt="Pantalla actual del dispositivo para toque o calibración"/>:<Empty>Conecta el dispositivo y actualiza la captura.</Empty>}<div className="button-row"><button disabled={!status.data?.available} onClick={()=>swipe.mutate('up')}>Deslizar arriba</button><button disabled={!status.data?.available} onClick={()=>swipe.mutate('down')}>Deslizar abajo</button><button disabled={!status.data?.available||inspect.isPending} onClick={()=>inspect.mutate()}>Leer texto</button><button disabled={!status.data?.available||inspectDcp.isPending} onClick={()=>inspectDcp.mutate()}>Leer requisitos DCP</button><button disabled={!status.data?.available||inspectObjectives.isPending} onClick={()=>inspectObjectives.mutate()}>Leer objetivos visibles</button></div>{inspection&&<div className="ocr-result"><strong>Lectura temporal</strong><pre>{inspection.raw_text||'No se detectó texto fiable'}</pre></div>}</section>

    {dcpInspection&&<section className="panel"><h3>Actualizar DCP visible</h3>{Object.keys(dcpInspection.detected_requirements).length?<><div className="tags">{Object.entries(dcpInspection.detected_requirements).map(([key,value])=><span key={key}>{key.replaceAll('_',' ')}: {value}</span>)}</div><label>Nombre exacto del DCP<input value={detectedDcpName} onChange={e=>setDetectedDcpName(e.target.value)}/></label><p>Revisa nombre y requisitos. Si el nombre ya existe se actualiza su segmento pendiente; no se crea un duplicado.</p><div className="confirmation-box"><p>Escribe <code>ACTUALIZAR DCP</code>.</p><div className="button-row"><input value={dcpConfirmation} onChange={e=>setDcpConfirmation(e.target.value)}/><button className="primary" disabled={syncDetectedDcp.isPending||!detectedDcpName.trim()||dcpConfirmation!=='ACTUALIZAR DCP'} onClick={()=>syncDetectedDcp.mutate()}>{syncDetectedDcp.isPending?'Actualizando…':'Guardar DCP revisado'}</button></div></div>{syncDetectedDcp.data&&<div className="alert info">DCP {syncDetectedDcp.data.action==='created'?'creado':'actualizado'} sin duplicarlo.</div>}</>:<div className="alert warning">No se detectaron requisitos fiables. Ajusta la pantalla y vuelve a leer.</div>}<p>El OCR puede equivocarse: el guardado siempre exige revisión y confirmación.</p></section>}
    {objectiveInspection&&<section className="panel"><h3>Actualizar objetivos visibles</h3><p>{objectiveInspection.message}. Solo se crean o actualizan los nombres visibles; los ausentes no se eliminan.</p>{objectiveInspection.objectives.length?<><div className="mini-list">{objectiveInspection.objectives.map(item=><span key={item.name}>{item.progress}/{item.target} · {item.name}</span>)}</div><div className="confirmation-box"><p>Comprueba la lista y escribe <code>ACTUALIZAR OBJETIVOS</code>.</p><div className="button-row"><input value={objectiveConfirmation} onChange={e=>setObjectiveConfirmation(e.target.value)}/><button className="primary" disabled={syncObjectives.isPending||objectiveConfirmation!=='ACTUALIZAR OBJETIVOS'} onClick={()=>syncObjectives.mutate()}>{syncObjectives.isPending?'Actualizando…':'Guardar objetivos revisados'}</button></div></div>{syncObjectives.data&&<div className="alert info">{syncObjectives.data.created} creados · {syncObjectives.data.updated} actualizados.</div>}</>:<div className="alert warning">No se reconocieron objetivos. Mantén abierta la pantalla Objetivos de Companion.</div>}</section>}

    <details className="panel" open><summary>Calibrar coordenadas DCP</summary><p>Toma una captura y marca cada zona directamente; el clic de calibración no se envía al dispositivo.</p><div className="button-row">{(Object.keys(calibrationPoints) as CalibrationTarget[]).map(target=><button className={calibrationTarget===target?'primary':''} key={target} disabled={!screen} onClick={()=>setCalibrationTarget(target)}>{target.replaceAll('_',' ')}</button>)}</div><div className="form-grid">{Object.entries(calibration).map(([key,value])=><label key={key}>{key.replaceAll('_',' ')}<input type="number" value={value} onChange={e=>setCalibration({...calibration,[key]:Number(e.target.value)})}/></label>)}<button className="primary wide" onClick={()=>saveCalibration.mutate()}>Guardar calibración</button></div></details>

    <section>
      <SectionTitle
        title="Sincronizar mi club real"
        subtitle="Carga completa en el servidor; revisión detallada paginada para ahorrar RAM"
        action={<div className="button-row">
          <button className="compact" disabled={scans.isFetching} onClick={()=>{void scans.refetch();void qc.invalidateQueries({queryKey:['inventory-scan-candidates']});void qc.invalidateQueries({queryKey:['inventory-bulk-preview']})}}>{scans.isFetching?'Actualizando…':'Actualizar revisión'}</button>
          <button className="primary compact" disabled={!status.data?.available||startScan.isPending||Boolean(activeScan)} onClick={()=>startScan.mutate()}>Nueva lectura</button>
        </div>}
      />
      <div className="alert warning">La fuente es la aplicación Companion abierta en el emulador. No hay sondeo automático: tú decides cuándo leerla con “Actualizar desde Companion”. ADB lee solo la pantalla visible y Ollama no participa.</div>
      {bulkPreview.data&&bulkPreview.data.detected>0&&<div className="panel" id="carga-completa"><div className="split"><div><span className="eyebrow">CARGA COMPLETA SIN DUPLICADOS</span><h3>{bulkPreview.data.unique_new} cartas únicas nuevas</h3><p>{bulkPreview.data.detected} detectadas en {bulkPreview.data.sessions} lecturas · {bulkPreview.data.duplicates} duplicadas · {bulkPreview.data.already_registered_or_used} ya registradas o usadas · {bulkPreview.data.incomplete} incompletas.</p></div><button disabled={reconcileScans.isPending} onClick={()=>reconcileScans.mutate()}>{reconcileScans.isPending?'Revisando…':'Limpiar duplicados pendientes'}</button></div><div className="alert warning">La carga global usa únicamente nombre, media y posición visibles. Liga, club y nacionalidad quedan como “No disponible” hasta que los corrijas. Revisa el resumen antes de confirmar.</div><div className="confirmation-box"><p>Para importar todas las cartas únicas de todos los lotes escribe <code>{bulkPreview.data.confirmation_phrase}</code>.</p><div className="button-row"><input value={bulkConfirmation} onChange={e=>setBulkConfirmation(e.target.value)} placeholder={bulkPreview.data.confirmation_phrase}/><button className="primary" disabled={bulkImport.isPending||bulkConfirmation!==bulkPreview.data.confirmation_phrase||bulkPreview.data.unique_new===0} onClick={()=>bulkImport.mutate()}>{bulkImport.isPending?'Cargando inventario completo…':'Cargar todo el club sin duplicados'}</button></div></div></div>}
      {bulkImport.data&&<div className="alert info">Carga terminada: {bulkImport.data.imported} cartas nuevas; {bulkImport.data.duplicates_skipped+bulkImport.data.registered_or_used_skipped} duplicadas o ya usadas omitidas.</div>}
      {openScans.length>1&&<div className="panel"><h3>Lecturas pendientes</h3><div className="button-row">{openScans.map(scan=><button key={scan.id} className={activeScan?.id===scan.id?'primary':''} onClick={()=>{setSelectedScanId(scan.id);changeReviewPage(1)}}>#{scan.id} · {scan.candidate_count} pendientes</button>)}</div></div>}
      {activeScan?<article className="panel">
        <div className={`ai-status ${status.data?.available?'online':'offline'}`}><span>●</span>{!status.data?.available?'Esperando que el emulador esté conectado':observeScan.isPending?'Leyendo la pantalla abierta de Companion…':'Listo para actualizar cuando tú lo indiques'}</div>
        <div className="split"><div><span className="eyebrow">LECTURA #{activeScan.id} · {activeScan.status.toUpperCase()}</span><h3>{activeScan.captured_pages} páginas · {activeScan.candidate_count} candidatos pendientes</h3></div><div className="button-row"><button disabled={captureScan.isPending||advanceScan.isPending} onClick={()=>captureScan.mutate(activeScan.id)}>Leer página actual</button><button className="primary" disabled={captureScan.isPending||advanceScan.isPending||activeScan.captured_pages<1||activeScan.captured_pages>=50||activeScan.candidate_count>=1000} onClick={()=>advanceScan.mutate(activeScan.id)}>Avanzar y leer siguiente</button>{(activeScan.captured_pages>=50||activeScan.candidate_count>=1000)&&<button className="primary" disabled={continueScan.isPending} onClick={()=>continueScan.mutate(activeScan.id)}>Continuar en un lote nuevo</button>}</div></div>
        <p>En Companion abre “Mi club → Futbolistas” y pulsa “Actualizar desde Companion”. Si cambias manualmente de página en el emulador, vuelve a pulsarlo. “Avanzar y leer siguiente” sigue disponible si quieres que la aplicación pulse únicamente el botón Siguiente validado. Una pantalla repetida no se agrega dos veces.</p>
        {activeScan.last_error&&<div className="alert warning">{activeScan.last_error}</div>}
        {activeScan.candidate_count>20&&<div className="button-row"><button disabled={reviewPage<=1||selectedPlayers.length>0} onClick={()=>changeReviewPage(reviewPage-1)}>Anterior</button><span>Página {Math.min(reviewPage,reviewPageCount)} de {reviewPageCount}</span><button disabled={reviewPage>=reviewPageCount||selectedPlayers.length>0} onClick={()=>changeReviewPage(reviewPage+1)}>Siguiente</button></div>}
        {selectedPlayers.length>0&&activeScan.candidate_count>20&&<p>Importa o desmarca la selección actual antes de cambiar de página.</p>}
        {scanCandidates.isLoading?<Loading/>:<div className="scan-grid">{reviewed.map(player=><div className="scan-candidate" key={player.candidate_id}><label className="check"><input type="checkbox" checked={player.selected} onChange={e=>updateReviewed(player.candidate_id,'selected',e.target.checked)}/> Importar</label><label>Nombre<input value={player.name} onChange={e=>updateReviewed(player.candidate_id,'name',e.target.value)}/></label><label>Media<input type="number" min="1" max="99" value={player.rating} onChange={e=>updateReviewed(player.candidate_id,'rating',Number(e.target.value))}/></label><label>Posición<input value={player.position} onChange={e=>updateReviewed(player.candidate_id,'position',e.target.value.toUpperCase())}/></label><label>Liga<input value={player.league} onChange={e=>updateReviewed(player.candidate_id,'league',e.target.value)}/></label><label>Club<input value={player.club} onChange={e=>updateReviewed(player.candidate_id,'club',e.target.value)}/></label><label>Nacionalidad<input value={player.nationality} onChange={e=>updateReviewed(player.candidate_id,'nationality',e.target.value)}/></label></div>)}</div>}
        {reviewed.length>0&&<div className="confirmation-box"><label className="check"><input type="checkbox" checked={archiveDemo} onChange={e=>{setArchiveDemo(e.target.checked);setScanConfirmation('')}}/> Archivar únicamente las 132 cartas demostrativas</label><p>Seleccionadas en esta página: {selectedPlayers.length}. Escribe exactamente <code>{expectedScanPhrase}</code>.</p><div className="button-row"><input value={scanConfirmation} onChange={e=>setScanConfirmation(e.target.value)}/><button className="primary" disabled={!selectedPlayers.length||scanConfirmation!==expectedScanPhrase||importScan.isPending} onClick={()=>importScan.mutate(activeScan)}>Importar página revisada</button></div></div>}
        {!scanCandidates.isLoading&&activeScan.candidate_count===0&&<Empty>No quedan candidatos pendientes en esta lectura.</Empty>}
        <button className="danger" disabled={cancelScan.isPending} onClick={()=>cancelScan.mutate(activeScan.id)}>Cancelar lectura</button>
      </article>:<Empty>Conecta el dispositivo y comienza una lectura. Las importaciones anteriores permanecen disponibles.</Empty>}
    </section>

    <section><SectionTitle title="Planes de combinaciones" subtitle="Coloca jugadores y se detiene antes de entregar"/>{plans.isLoading?<Loading/>:!plans.data?.length?<Empty>Optimiza un DCP y pulsa “Preparar en emulador”.</Empty>:<div className="stack">{plans.data.map(plan=><article className="panel" key={plan.id}><div className="split"><div><span className="eyebrow">PLAN #{plan.id} · {plan.status.toUpperCase()}</span><h3>{plan.name}</h3><p>{plan.solution_snapshot.players.map(p=>`${p.rating} ${p.name}`).join(' · ')}</p></div><strong>{plan.progress_step}/{plan.steps.length}</strong></div>{plan.last_error&&<div className="error-box">{plan.last_error}</div>}{plan.status==='draft'&&<button className="primary" onClick={()=>prepare.mutate(plan.id)}>Preparar pulsaciones</button>}{plan.status==='prepared'&&<div className="confirmation-box"><p>Para iniciar escribe exactamente <code>{plan.confirmation_phrase}</code>.</p><div className="button-row"><input value={confirmations[plan.id]||''} onChange={e=>setConfirmations({...confirmations,[plan.id]:e.target.value})}/><button className="primary" disabled={confirmations[plan.id]!==plan.confirmation_phrase} onClick={()=>execute.mutate(plan)}>Ejecutar preparación</button></div></div>}{['queued','running'].includes(plan.status)&&<button className="danger" onClick={()=>cancel.mutate(plan.id)}>Detener plan</button>}{plan.status==='completed'&&<div className="alert warning">Preparación terminada. Comprueba jugadores y requisitos; solo tú debes pulsar la entrega final.</div>}</article>)}</div>}</section>
    {anyError&&<ErrorBox error={anyError}/>}<div className="alert warning">No realiza compras, ventas, inicio de sesión ni la pulsación final de entrega.</div>
  </>
}

function SettingsPage({dark,setDark}:{dark:boolean;setDark:(value:boolean)=>void}){
  const qc=useQueryClient(); const profile=useQuery({queryKey:['profile'],queryFn:()=>api<Dashboard['profile']>('/profile')}); const [ocr,setOcr]=useState<{raw_text:string;candidates:{name:string;rating:number|null;position:string;confidence:Record<string,number>}[]}|null>(null); const [backupId,setBackupId]=useState('')
  const form=useForm({defaultValues:{name:'',coins:0,platform:'Consola',max_budget:0,risk_level:'medio'}})
  useEffect(()=>{if(profile.data)form.reset(profile.data)},[profile.data,form])
  const save=useMutation({mutationFn:(v:Record<string,unknown>)=>api('/profile',{method:'PATCH',body:JSON.stringify(v)}),onSuccess:()=>{qc.invalidateQueries({queryKey:['profile']});qc.invalidateQueries({queryKey:['dashboard']})}})
  const ocrMutation=useMutation({mutationFn:async(file:File)=>{const data=new FormData();data.append('file',file);return api<typeof ocr>('/ocr/preview',{method:'POST',body:data})},onSuccess:data=>setOcr(data)})
  const restore=useMutation({mutationFn:()=>api(`/submissions/${Number(backupId)}/restore`,{method:'POST'}),onSuccess:()=>{qc.invalidateQueries();setBackupId('')}})
  return <><SectionTitle title="Configuración" subtitle="Preferencias almacenadas solo en este equipo"/><form className="panel form-grid" onSubmit={form.handleSubmit(v=>save.mutate(v))}><h3 className="wide">Perfil local</h3><label className="wide">Nombre del club<input {...form.register('name')}/></label><label>Monedas<input type="number" {...form.register('coins',{valueAsNumber:true})}/></label><label>Presupuesto máximo<input type="number" {...form.register('max_budget',{valueAsNumber:true})}/></label><label>Plataforma<select {...form.register('platform')}><option>Consola</option><option>PC</option><option>Switch</option></select></label><label>Riesgo<select {...form.register('risk_level')}><option>bajo</option><option>medio</option><option>alto</option></select></label><button className="primary wide">Guardar preferencias</button></form>
    <section className="panel"><div className="split"><div><h3>Apariencia</h3><p>Interfaz adaptable a la preferencia del dispositivo.</p></div><button onClick={()=>setDark(!dark)}>{dark?'Usar modo claro':'Usar modo oscuro'}</button></div></section>
    <section className="panel"><h3>Revisión OCR de una captura</h3><p>JPEG, PNG o WebP, máximo 10 MB. El resultado nunca se guarda sin revisión manual.</p><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>{const f=e.target.files?.[0];if(f)ocrMutation.mutate(f)}}/>{ocrMutation.isPending&&<Loading/>}{ocr&&<div className="ocr-result"><strong>Texto detectado</strong><pre>{ocr.raw_text||'Sin texto fiable'}</pre>{ocr.candidates.map((c,i)=><p key={i}>Nombre: {c.name||'por revisar'} · Media: {c.rating||'por revisar'} · Posición: {c.position||'por revisar'}</p>)}<div className="alert warning">Corrige todos los campos en “Club” antes de registrar una carta.</div></div>}{ocrMutation.error&&<ErrorBox error={ocrMutation.error}/>}</section>
    <section className="panel"><h3>Restaurar una entrega DCP</h3><p>Introduce el identificador mostrado al confirmar. Se reactiva exactamente el estado previo de esas cartas.</p><div className="button-row"><input value={backupId} inputMode="numeric" onChange={e=>setBackupId(e.target.value.replace(/\D/g,''))} placeholder="ID de entrega"/><button disabled={!backupId} onClick={()=>restore.mutate()}>Restaurar</button></div>{restore.error&&<ErrorBox error={restore.error}/>}</section>
    <section className="panel"><h3>Copias de seguridad</h3><p>Usa <code>make backup</code> o <code>scripts/backup.ps1</code>. Las copias quedan en <code>./backups/</code> y nunca se suben a Git.</p></section></>
}

export default App
